import math

def sigmoid(z):
    return 1 / (1 + math.exp(-z))

def odds_from_prob(p):
    return p / (1 - p)

def prob_from_odds(odds):
    return odds / (1 + odds)

import math

def log_loss(y, p):
    # y: list of 0s and 1s; p: list of probabilities of a 1
    total = 0.0
    for yi, pi in zip(y, p):
        total += yi * math.log(pi) + (1 - yi) * math.log(1 - pi)
    return -total / len(y)
